package com.oai.harmonywake; import org.json.*; public class WakeTask { public int id,hour,minute,screenMinutes; public String packageName,appName; public boolean enabled; public WakeTask(int i,int h,int m,String p,String a,int s,boolean e){id=i;hour=h;minute=m;packageName=p;appName=a;screenMinutes=s;enabled=e;} JSONObject toJson() throws JSONException {JSONObject o=new JSONObject();o.put("id",id);o.put("hour",hour);o.put("minute",minute);o.put("packageName",packageName);o.put("appName",appName);o.put("screenMinutes",screenMinutes);o.put("enabled",enabled);return o;} static WakeTask fromJson(JSONObject o)throws JSONException{return new WakeTask(o.getInt("id"),o.getInt("hour"),o.getInt("minute"),o.optString("packageName",""),o.optString("appName",""),o.optInt("screenMinutes",10),o.optBoolean("enabled",true));}}